'use strict';
const net = require('net');
const crypto = require('crypto');

const MAX_FRAME_SIZE = 65536;
const AUTH_TIMEOUT_MS = 5000;
const sessions = new Map();

function loadConfig() {
  return {
    port: parseInt(process.env.BINARY_PROTO_PORT || '9100', 10),
    secret: process.env.BINARY_PROTO_SECRET || crypto.randomBytes(32).toString('hex'),
    maxConnections: parseInt(process.env.MAX_CONNECTIONS || '100', 10),
    allowedSubnets: (process.env.ALLOWED_SUBNETS || '127.0.0.1').split(',')
  };
}

function verifyHmac(data, signature, secret) {
  const expected = crypto.createHmac('sha256', secret).update(data).digest();
  const sigBuf = Buffer.from(signature, 'hex');
  if (sigBuf.length !== expected.length) return false;
  return crypto.timingSafeEqual(sigBuf, expected);
}

function isAllowedSource(remoteAddr, allowedSubnets) {
  const addr = remoteAddr.replace('::ffff:', '');
  return allowedSubnets.some(subnet => addr === subnet.trim());
}

// Binary frame format:
// [1 byte opcode][4 bytes payload length (big-endian unsigned)][payload]
// Opcodes: 0x01=AUTH, 0x02=DATA, 0x03=PING, 0x04=CLOSE

function parseFrame(buffer, offset) {
  if (offset + 5 > buffer.length) return null;

  const opcode = buffer[offset];
  const payloadLength = buffer.readUInt32BE(offset + 1);

  // Bounds check: ensure we have enough data
  // Using bitwise OR to ensure integer arithmetic
  const totalNeeded = (offset + 5 + payloadLength) | 0;
  if (totalNeeded > buffer.length) return null;
  if (payloadLength > MAX_FRAME_SIZE) return null;

  const payload = buffer.slice(offset + 5, offset + 5 + payloadLength);
  return { opcode, payload, bytesConsumed: 5 + payloadLength };
}

function handleAuth(socket, payload, config) {
  try {
    const msg = JSON.parse(payload.toString('utf8'));
    if (!msg.username || !msg.timestamp || !msg.signature) {
      socket.write(Buffer.from([0x04, 0x00, 0x00, 0x00, 0x01, 0x01]));
      socket.end();
      return false;
    }

    const now = Date.now();
    if (Math.abs(now - msg.timestamp) > 30000) {
      socket.write(Buffer.from([0x04, 0x00, 0x00, 0x00, 0x01, 0x02]));
      socket.end();
      return false;
    }

    const authData = `${msg.username}:${msg.timestamp}`;
    if (!verifyHmac(authData, msg.signature, config.secret)) {
      socket.write(Buffer.from([0x04, 0x00, 0x00, 0x00, 0x01, 0x03]));
      socket.end();
      return false;
    }

    sessions.set(socket, { username: msg.username, authenticated: true });
    socket.write(Buffer.from([0x01, 0x00, 0x00, 0x00, 0x02, 0x4F, 0x4B]));
    return true;
  } catch (e) {
    socket.end();
    return false;
  }
}

function handleData(socket, payload) {
  const session = sessions.get(socket);
  if (!session || !session.authenticated) {
    socket.write(Buffer.from([0x04, 0x00, 0x00, 0x00, 0x01, 0x04]));
    return;
  }

  // Echo back the data with a response frame
  const respLen = Buffer.alloc(4);
  respLen.writeUInt32BE(payload.length, 0);
  socket.write(Buffer.concat([Buffer.from([0x02]), respLen, payload]));
}

function processBuffer(socket, config) {
  const state = sessions.get(socket) || { buffer: Buffer.alloc(0) };
  let buf = state.buffer;
  let offset = 0;

  while (offset < buf.length) {
    const frame = parseFrame(buf, offset);
    if (!frame) break;

    switch (frame.opcode) {
      case 0x01:
        handleAuth(socket, frame.payload, config);
        break;
      case 0x02:
        handleData(socket, frame.payload);
        break;
      case 0x03:
        socket.write(Buffer.from([0x03, 0x00, 0x00, 0x00, 0x00]));
        break;
      case 0x04:
        socket.end();
        return;
      default:
        socket.end();
        return;
    }
    offset += frame.bytesConsumed;
  }

  if (offset > 0) {
    state.buffer = buf.slice(offset);
  }
  if (!sessions.has(socket)) {
    sessions.set(socket, { ...state, buffer: state.buffer });
  }
}

function createServer(config) {
  const server = net.createServer((socket) => {
    if (!isAllowedSource(socket.remoteAddress, config.allowedSubnets)) {
      socket.end();
      return;
    }

    if (sessions.size >= config.maxConnections) {
      socket.end();
      return;
    }

    sessions.set(socket, { buffer: Buffer.alloc(0), authenticated: false });

    const authTimer = setTimeout(() => {
      const sess = sessions.get(socket);
      if (!sess || !sess.authenticated) {
        socket.end();
      }
    }, AUTH_TIMEOUT_MS);

    socket.on('data', (data) => {
      const state = sessions.get(socket);
      if (!state) return;
      state.buffer = Buffer.concat([state.buffer, data]);

      if (state.buffer.length > MAX_FRAME_SIZE * 2) {
        socket.end();
        return;
      }

      processBuffer(socket, config);
    });

    socket.on('close', () => {
      clearTimeout(authTimer);
      sessions.delete(socket);
    });

    socket.on('error', () => {
      clearTimeout(authTimer);
      sessions.delete(socket);
    });
  });

  return server;
}

const config = loadConfig();
const server = createServer(config);
server.listen(config.port, '127.0.0.1', () => {
  console.log(`Binary protocol server on port ${config.port}`);
});

module.exports = { parseFrame, verifyHmac, createServer, loadConfig };
